      "description": "First day of the reporting window, YYYY-MM-DD",
      "schema": {
        "type": "string"
      }
    },
    {
      "name": "end_date",
      "in": "query",
      "required": true,
      "description": "Last day of the reporting window, inclusive, YYYY-MM-DD",
      "schema": {
        "type": "string"
      }
    },
    {
      "name": "cursor",
      "in": "query",
      "description": "Opaque pagination cursor from a previous response",
      "schema": {
        "type": "string"
      }
    },
    {
      "name": "page_size",
      "in": "query",
      "description": "Results per page, 1 to 100 (default 20)",
      "schema": {
        "type": "integer"
      }
    }
  ],
  "responses": [
    {
      "status": "200",
      "description": "Successful response",
      "content_types": [
        "application/json"
      ],
      "schema": {
        "properties": {
          "items": {
            "description": "One page of results",
            "items": {
              "properties": {
                "date": {
                  "description": "Day of the series, YYYY-MM-DD",
                  "type": "string"
                },
                "sentiment_score": {
                  "description": "Net sentiment on the day, 0 (negative) to 100 (positive)",
                  "type": "integer"
                },
                "volume": {
                  "description": "Matching mentions on the day",
                  "type": "integer"
                }
              },
              "type": "object"
            },
            "type": "array"
          },
          "next_cursor": {
            "description": "Cursor for the next page; absent on the last page",
            "type": "string"
          }
        },
        "type": "object"
      }
    },
    {
      "status": "403",
      "description": "The credential is not entitled to this product area. Distinct from a successful response carrying an empty collection, which means the account has none of the resource.",
      "content_types": [
        "application/json"
